def plot(r):
    import matplotlib
    matplotlib.use('Agg')
    import matplotlib.pyplot as plt
    plt.rcParams.update({'font.family': 'DejaVu Sans', 'font.size': 10})
    fig, axes = plt.subplots(1, 2, figsize=(12.5, 5.2))
    dem = r['terrain']; pts = dem['points']; x = np.array([v['longitude'] for v in pts]); y = np.array([v['latitude'] for v in pts]); v = np.array([q['elevation_m'] for q in pts])
    a = axes[0]; sc = a.scatter(x, y, c=v, s=380, cmap='terrain', edgecolor='white')
    for xx, yy, zz in zip(x, y, v): a.text(xx, yy, f'{zz:.0f}', ha='center', va='center', fontsize=9)
    a.scatter([r['point']['longitude']], [r['point']['latitude']], s=600, facecolors='none', edgecolors='#b23630', linewidths=2, label='Рабочая точка', zorder=5)
    a.annotate(f"{dem['point_elevation_estimate_m']:.0f}", (r['point']['longitude'], r['point']['latitude']), ha='center', va='center', fontsize=9, zorder=6)
    a.set(title='DEM: выборочные высоты в окрестности, м', xlabel='Долгота', ylabel='Широта'); a.ticklabel_format(useOffset=False, style='plain'); a.set_aspect(1.414)
    a.set_xticks([float(x.min()), r['point']['longitude'], float(x.max())])
    a.margins(x=.10, y=.10)
    a.legend(loc='upper left', bbox_to_anchor=(0, -.16), frameon=False)
    fig.colorbar(sc, ax=a, pad=.02, shrink=.85)
    a = axes[1]; xx = np.arange(3); years = [str(y) for y in [2022, 2023, 2024]]
    a.bar(xx-.17, [100*r['krymsk']['years'][y]['temperature_present']/736 for y in years], .34, color='#2d7785', label='Крымск: трёхчасовые сроки')
    counts = [sum(q['years'][y]['qc_accepted'] for q in r['daily_sources'].values()) for y in years]
    a.bar(xx+.17, [100*c/(92*3) for c in counts], .34, color='#b58c60', label='3 GHCN-станции: суточные Tmin')
    a.set_xticks(xx, years); a.set(ylim=(0, 112), ylabel='Доступно от ожидаемого, %', title='Полнота доступных рядов, разные цели')
    for i, y in enumerate(years):
        a.text(i-.17, 102, f"{r['krymsk']['years'][y]['temperature_present']}/736", ha='center', fontsize=9)
        a.text(i+.17, counts[i]/276*100+3, f'{counts[i]}/276', ha='center', fontsize=9)
    a.legend(loc='upper left', bbox_to_anchor=(0, -.16), frameon=False, fontsize=9)
    fig.suptitle('Рабочая зона 45.024106, 37.911914: данные для проверки, не оценка точности', y=.99)
    fig.text(.5, .02, 'Copernicus DEM GLO-90 / Open-Meteo · Погода и климат · NOAA GHCN-D. Контур сада неизвестен.', ha='center', fontsize=9)
    fig.subplots_adjust(left=.07, right=.98, top=.83, bottom=.24, wspace=.3)
    path = ROOT/'docs/assets/farm-data-research.png'; fig.savefig(path, dpi=160); plt.close(fig)


if __name__ == '__main__': build()
